const r = $json || {};
const plan = r.plan || {};
const registry = Array.isArray(r.providerRegistry) ? r.providerRegistry : [];
const resource = r.resourceState || {};
const policy = r.policy || {};
const errors = [];
const tasks = Array.isArray(plan.tasks) ? plan.tasks : [];

const eligible = registry.filter(p => {
  if (!p || p.enabled !== true) return false;
  if (p.health && !['healthy','operational'].includes(String(p.health).toLowerCase())) return false;
  if (p.credentialsReady === false || p.endpointReady === false) return false;
  if (p.permissionAllowed === false) return false;
  if (p.maintenance === true) return false;
  return true;
});

const memoryPressure = Number(resource.memoryPressure ?? 0);
const cpuPressure = Number(resource.cpuPressure ?? 0);
const networkAvailable = resource.networkAvailable !== false;
const allowRemote = policy.allowRemote !== false;
const maxPressure = Number(policy.maxPressure ?? 85);

function candidateFor(task) {
  const required = new Set(Array.isArray(task.capabilityRequirements) ? task.capabilityRequirements.map(String) : []);
  const requestedProviders = new Set(Array.isArray(task.candidateProviders) ? task.candidateProviders.map(String) : []);
  const requestedModels = new Set(Array.isArray(task.candidateModels) ? task.candidateModels.map(String) : []);
  const candidates = eligible.filter(p => {
    const caps = new Set(Array.isArray(p.capabilities) ? p.capabilities.map(String) : []);
    const capabilityMatch = required.size === 0 || [...required].every(x => caps.has(x));
    const providerMatch = requestedProviders.size === 0 || requestedProviders.has(String(p.providerId ?? p.name));
    const modelMatch = requestedModels.size === 0 || (Array.isArray(p.models) && p.models.some(m => requestedModels.has(String(m))));
    const remote = String(p.executionMode ?? 'remote').toLowerCase() === 'remote';
    return capabilityMatch && providerMatch && modelMatch && (allowRemote || !remote) && (networkAvailable || !remote);
  });
  candidates.sort((a,b) => Number(a.priority ?? 999) - Number(b.priority ?? 999));
  if (!candidates.length) return { status: 'unavailable', reason: 'no_eligible_provider_or_model' };
  if (cpuPressure >= maxPressure || memoryPressure >= maxPressure) return { status: 'deferred', reason: 'resource_pressure', candidates: candidates.map(x => String(x.providerId ?? x.name)) };
  const p = candidates[0];
  return { status: 'selected', providerId: p.providerId ?? p.name, model: p.selectedModel ?? (Array.isArray(p.models) ? p.models[0] : null), executionMode: p.executionMode ?? 'remote' };
}

const selections = tasks.map(task => ({ taskId: task.taskId, selection: candidateFor(task) }));
const failed = selections.filter(x => x.selection.status === 'unavailable');
const deferred = selections.filter(x => x.selection.status === 'deferred');
if (!tasks.length) errors.push('plan_tasks_required');
if (failed.length) errors.push('provider_selection_unavailable');

return {
  valid: errors.length === 0,
  errors,
  schema: 'jarvis.compatible.model-selection.v1',
  requestId: r.requestId, traceId: r.traceId, sessionId: r.sessionId, jobId: r.jobId || null,
  stage: 'model-selection',
  selections,
  eligibleProviderCount: eligible.length,
  deferredCount: deferred.length,
  resourceGate: { cpuPressure, memoryPressure, networkAvailable, maxPressure },
  executionAllowed: errors.length === 0 && deferred.length === 0,
  executionReason: errors.length ? 'selection_failed' : deferred.length ? 'resource_gate_deferred' : 'selection_complete; execution still requires permission, approval, scheduler, and tool gateway',
  selectedAt: new Date().toISOString()
};
